#!/bin/bash
# The vp2 kit's QEMU firmware (fw_jump.elf), by the recipe that built 6f2b082cb677f026 (deleg-gate2's buildT-fw.sh):
# OpenSBI cf344cf3 + a capstone-sbi COMMIT, the monitor C generated by capstone-c with the kit's QEMU defines and checked
# by buildroot 8fd1ea12's check-monitor-asm.py, then make PLATFORM=generic. MODE=plain|inject: inject adds
# -DCAPSTONE_S_TRAP_INJECT to capstone-c and to the generic platform's cpp/c/as flags (the entry is assembled by make).
# Usage: build-kit-qemu-fw.sh <capstone-sbi commit> <plain|inject> <fresh output dir>
main() {
  set -u
  local MON=${1:?capstone-sbi commit} MODE=${2:?plain or inject} F=${3:?output dir}
  local R=$HOME/dev/llvm-capstone/capstone CC=$HOME/dev/llvm-capstone/capstone/capstone-c/target/debug/capstone-c
  local X=$R/caplifive-buildroot/build/host/bin/riscv64-buildroot-linux-gnu- SBI=/tmp/capstone/csbi-land
  local DEFS="-DCAPSTONE_TARGET_QEMU -DCAPSTONE_DEBUG_ENABLE -DCAPSTONE_SUPERVISED_CALL"
  case $MODE in plain) ;; inject) DEFS="$DEFS -DCAPSTONE_S_TRAP_INJECT";; *) echo "STOP: mode"; return 1;; esac
  [ -e "$F" ] && { echo "STOP: $F exists"; return 1; }
  mkdir -p "$F/src"
  git -C $R/caplifive-buildroot/components/opensbi archive cf344cf3884f | tar -x -C "$F/src" || return 3
  mkdir -p "$F/src/lib/sbi/capstone-sbi"
  git -C $SBI archive "$MON" | tar -x -C "$F/src/lib/sbi/capstone-sbi" || return 3
  git -C $R/caplifive-buildroot show 8fd1ea1249a9:scripts/check-monitor-asm.py > "$F/check-monitor-asm.py" || return 3
  local w rc ck
  for w in sbi_capstone_dom capstone_int_handler; do
    $CC --abi capstone "$F/src/lib/sbi/$w.c" -- -I"$F/src/lib/sbi/capstone-sbi" -D__riscv_xlen=64 $DEFS > "$F/src/lib/sbi/$w.c.S" 2> "$F/$w.cc.log"; rc=$?
    python3 "$F/check-monitor-asm.py" "$F/src/lib/sbi/$w.c.S" > "$F/$w.check.log" 2>&1; ck=$?
    echo "  $w.c.S: capstone-c rc=$rc, $(wc -l < "$F/src/lib/sbi/$w.c.S") lines, check-monitor-asm rc=$ck"
    [ $rc = 0 ] && [ $ck = 0 ] && [ -s "$F/src/lib/sbi/$w.c.S" ] || return 3
  done
  if [ $MODE = inject ]; then
    local M="$F/src/platform/generic/objects.mk"
    [ "$(grep -c '^platform-\(cppflags\|cflags\|asflags\)-y = -DCAPSTONE_TARGET_QEMU -DCAPSTONE_DEBUG_ENABLE$' $M)" = 3 ] || { echo "STOP: objects.mk flags not as expected"; return 3; }
    sed -i 's/^\(platform-\(cppflags\|cflags\|asflags\)-y = -DCAPSTONE_TARGET_QEMU -DCAPSTONE_DEBUG_ENABLE\)$/\1 -DCAPSTONE_S_TRAP_INJECT/' $M
    [ "$(grep -c 'CAPSTONE_S_TRAP_INJECT' $M)" = 3 ] || { echo "STOP: the define did not reach objects.mk"; return 3; }
  fi
  taskset -c 16-23 nice -n 10 ionice -c3 make -C "$F/src" PLATFORM=generic CROSS_COMPILE=$X -j6 > "$F/make.log" 2>&1; rc=$?
  [ $rc = 0 ] || { tail -5 "$F/make.log"; return 3; }
  cp "$F/src/build/platform/generic/firmware/fw_jump.elf" "$F/fw_jump.elf"
  echo "fw_jump.elf $(sha256sum < "$F/fw_jump.elf" | cut -c1-16) mode $MODE monitor $(git -C $SBI rev-parse --short=7 "$MON")"
  echo "  _inject_s_trap in sbi_capstone_init.o: $(nm "$F/src/build/lib/sbi/sbi_capstone_init.o" 2>/dev/null | grep -c ' _inject_s_trap$')"
}
main "$@"; exit $?
